// src/components/dashboard/KpiCards.tsx
import React from 'react';
import { Paper, Typography, Box, List, ListItem, ListItemText, Divider, useTheme, Stack, Grid, LinearProgress, alpha } from '@mui/material';
import { useSubjectColors } from '../../contexts/SubjectColorsContext';
import KpiBreakdownPieChart from './KpiBreakdownPieChart';

type SubjectBreakdown = {
    name: string;
    count: number;
    average: number;
    totalCorrect: number;
    totalQuestions: number;
};

type DashboardStats = {
    totalQuizzes: number;
    overallAverageScore: number;
    subjectBreakdowns: Record<string, SubjectBreakdown>;
    overallQuestionStats: { total: number; correct: number; accuracy: number };
};

type ChartBreakdown = { name: string; count: number };
type ListBreakdown = { name: string; average: number; totalQuestions: number; totalCorrect: number };

const AverageScoreCard = ({ value, caption, breakdownData, overallQuestionStats }: { value: string; caption: string; breakdownData: Record<string, any>; overallQuestionStats?: { total: number; correct: number; accuracy: number } }) => {
    const theme = useTheme();
    const { getColor } = useSubjectColors();

    return (
        <Paper elevation={3} sx={{ p: { xs: 2, sm: 2.5 }, border: `1px solid ${theme.palette.divider}`, height: '100%' }}>
            <Box sx={{ textAlign: 'center' }}>
                <Typography variant="h6" color="text.secondary" sx={{ fontSize: { xs: '1rem', sm: '1.125rem' } }}>
                    Overall Average Score
                </Typography>
                <Typography variant="h3" sx={{ color: 'text.primary', fontWeight: 'bold', fontSize: { xs: '2rem', sm: '2.5rem' } }}>
                    {value}
                </Typography>
                <Typography variant="caption" color="text.secondary">{caption}</Typography>
            </Box>

            <Box sx={{ my: 2 }}>
                <LinearProgress
                    variant="determinate"
                    value={parseFloat(value)}
                    sx={{
                        height: 8,
                        borderRadius: 4,
                        backgroundColor: alpha(theme.palette.primary.main, 0.2),
                        '& .MuiLinearProgress-bar': { backgroundColor: theme.palette.primary.main }
                    }}
                />
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 0.5 }}>
                    <Typography variant="caption" color="text.secondary">
                        {overallQuestionStats?.correct || 0} Correct
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                        {overallQuestionStats?.total || 0} Questions
                    </Typography>
                </Box>
            </Box>

            <List dense sx={{ pt: 1, textAlign: 'left' }}>
                <Divider sx={{ mb: 1.5 }} />
                {Object.entries(breakdownData).length > 0 ? Object.entries(breakdownData).map(([subjectKey, data]) => (
                    <ListItem key={subjectKey} dense disableGutters sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
                        <Box sx={{ width: '100%', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <Typography variant="body1" sx={{ color: getColor(subjectKey), fontWeight: 500 }}>
                                {data.name}
                            </Typography>
                            <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                {data.average}%
                            </Typography>
                        </Box>
                        <LinearProgress
                            variant="determinate"
                            value={data.average}
                            sx={{
                                height: 6,
                                borderRadius: 3,
                                width: '100%',
                                mt: 0.5,
                                backgroundColor: alpha(getColor(subjectKey), 0.2),
                                '& .MuiLinearProgress-bar': { backgroundColor: getColor(subjectKey) }
                            }}
                        />
                        {/* --- START OF FIX: Display correct/total questions --- */}
                        <Typography variant="caption" color="text.secondary" sx={{ alignSelf: 'flex-end' }}>
                            {`${data.totalCorrect} / ${data.totalQuestions} Correct`}
                        </Typography>
                        {/* --- END OF FIX --- */}
                    </ListItem>
                )) : <Typography variant="caption" color="text.secondary">No subject data.</Typography>}
            </List>
        </Paper>
    );
};

function KpiCards({ stats, isLoading }: { stats: DashboardStats | null; isLoading: boolean }) {
    const { getColor } = useSubjectColors();

    // Loading or empty state handling
    if (isLoading) {
        return (
            <Stack spacing={2}>
                <Paper data-testid="kpi-card-loading" elevation={3} sx={{ p: 2 }} />
                <Paper data-testid="kpi-card-loading" elevation={3} sx={{ p: 2 }} />
                <Paper data-testid="kpi-card-loading" elevation={3} sx={{ p: 2 }} />
                <Paper data-testid="kpi-card-loading" elevation={3} sx={{ p: 2 }} />
            </Stack>
        );
    }

    const totalQuizzes = stats?.totalQuizzes ?? 0;
    const averageScore = stats?.overallAverageScore ?? 0;
    const isFiltered = false;
    const overallQuestionStats = stats?.overallQuestionStats ?? { total: 0, correct: 0, accuracy: 0 };

    // Handle null/undefined subjectBreakdowns
    const safeSubjectBreakdowns: Record<string, SubjectBreakdown> = stats?.subjectBreakdowns ?? {} as Record<string, SubjectBreakdown>;

    const quizzesBreakdownForChart: Record<string, ChartBreakdown> = Object.entries(safeSubjectBreakdowns).reduce(
        (acc: Record<string, ChartBreakdown>, [key, value]) => {
            acc[key] = { name: value.name, count: value.count };
            return acc;
        },
        {}
    );
    
    // Pass all necessary data points through to the card component
    const scoresBreakdownForList: Record<string, ListBreakdown> = Object.entries(safeSubjectBreakdowns).reduce(
        (acc: Record<string, ListBreakdown>, [key, value]) => {
            acc[key] = {
                name: value.name,
                average: value.average,
                totalQuestions: value.totalQuestions,
                totalCorrect: value.totalCorrect
            };
            return acc;
        },
        {}
    );

    return (
        <Stack spacing={2}>
            {/* Top Card: Total Quizzes Solved */}
            <Paper elevation={3} sx={{ p: { xs: 2, sm: 2.5 }, border: `1px solid theme.palette.divider` }}>
                <Typography variant="h6" color="text.secondary" sx={{ fontSize: { xs: '1rem', sm: '1.125rem' }, textAlign: 'center', mb: 2 }}>
                    Total Quizzes Solved
                </Typography>
                <Grid container spacing={1} alignItems="center">
                    <Grid item xs={12} md={4}>
                        <List dense sx={{ textAlign: 'left', p: 0 }}>
                            {Object.entries(quizzesBreakdownForChart).map(([key, data]) => (
                                <ListItem key={key} dense disableGutters>
                                    <ListItemText
                                        primary={data.name}
                                        primaryTypographyProps={{ sx: { color: getColor(key), fontWeight: 'bold' } }}
                                        secondary={`${data.count} quiz(zes)`}
                                    />
                                </ListItem>
                            ))}
                        </List>
                    </Grid>
                    <Grid item xs={12} md={4} sx={{ textAlign: 'center' }}>
                        <Typography variant="h2" sx={{ color: 'text.primary', fontWeight: 'bold' }}>
                            {totalQuizzes}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                            {isFiltered ? '(in selected filter)' : '(in selected period)'}
                        </Typography>
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <KpiBreakdownPieChart breakdownData={quizzesBreakdownForChart} />
                    </Grid>
                </Grid>
            </Paper>
            
            {/* Bottom Card: Overall Average Score */}
            <AverageScoreCard
                value={`${averageScore}%`}
                caption={isFiltered ? '(in selected filter)' : '(in selected period)'}
                breakdownData={scoresBreakdownForList}
                overallQuestionStats={overallQuestionStats}
            />
        </Stack>
    );
}

export default KpiCards;